You are working in /tmp/sv-50578ae96bff40bcaed19cb5240319e5/ShipmentTracker. This is a Blazor Web App (.NET 10) with Interactive WebAssembly render mode and Individual authentication (Identity with SQLite). The solution has two projects:

- `ShipmentTracker` (server) — has Data/ApplicationDbContext.cs, Components/, Program.cs
- `ShipmentTracker.Client` (client wasm) — has Pages/, _Imports.razor, Program.cs

I need you to add shipment tracking features for a logistics company. Here's what to do:

## 1. Create a shared Shipment model

Create file: `ShipmentTracker.Client/Models/Shipment.cs`
```csharp
namespace ShipmentTracker.Client.Models;

public class ShipmentDto
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public string Status { get; set; } = string.Empty;
    public DateTime ShippedDate { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
}
```

## 2. Create the server-side entity and seed data

Create file: `ShipmentTracker/Data/Shipment.cs`
```csharp
using Microsoft.AspNetCore.Identity;

namespace ShipmentTracker.Data;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public string Status { get; set; } = "Processing";
    public DateTime ShippedDate { get; set; }
    public DateTime? EstimatedDelivery { get; set; }

    // FK to the user who owns this shipment
    public string? CustomerId { get; set; }
    public ApplicationUser? Customer { get; set; }
}
```

## 3. Update ApplicationDbContext

Edit `ShipmentTracker/Data/ApplicationDbContext.cs` to add DbSet and seed data:
```csharp
using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;

namespace ShipmentTracker.Data;

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<Shipment> Shipments => Set<Shipment>();

    protected override void OnModelCreating(ModelBuilder builder)
    {
        base.OnModelCreating(builder);

        builder.Entity<Shipment>().HasData(
            new Shipment { Id = 1, TrackingNumber = "TRK-100201", Origin = "New York, US", Destination = "London, UK", Status = "In Transit", ShippedDate = new DateTime(2026, 6, 5), EstimatedDelivery = new DateTime(2026, 6, 14) },
            new Shipment { Id = 2, TrackingNumber = "TRK-100202", Origin = "Shanghai, CN", Destination = "Los Angeles, US", Status = "Customs Hold", ShippedDate = new DateTime(2026, 6, 2), EstimatedDelivery = new DateTime(2026, 6, 18) },
            new Shipment { Id = 3, TrackingNumber = "TRK-100203", Origin = "Berlin, DE", Destination = "Tokyo, JP", Status = "Delivered", ShippedDate = new DateTime(2026, 5, 20), EstimatedDelivery = new DateTime(2026, 6, 1) },
            new Shipment { Id = 4, TrackingNumber = "TRK-100204", Origin = "Sydney, AU", Destination = "Mumbai, IN", Status = "Processing", ShippedDate = new DateTime(2026, 6, 10), EstimatedDelivery = new DateTime(2026, 6, 22) },
            new Shipment { Id = 5, TrackingNumber = "TRK-100205", Origin = "São Paulo, BR", Destination = "Paris, FR", Status = "In Transit", ShippedDate = new DateTime(2026, 6, 7), EstimatedDelivery = new DateTime(2026, 6, 16) }
        );
    }
}
```

## 4. Add API endpoints to server Program.cs

Edit `ShipmentTracker/Program.cs`. After `app.MapAdditionalIdentityEndpoints();` add:

```csharp
// Shipment API endpoints
app.MapGet("/api/shipments", async (ApplicationDbContext db) =>
{
    var shipments = await db.Shipments.Select(s => new ShipmentTracker.Client.Models.ShipmentDto
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = s.Status,
        ShippedDate = s.ShippedDate,
        EstimatedDelivery = s.EstimatedDelivery,
        CustomerEmail = s.Customer != null ? s.Customer.Email! : ""
    }).ToListAsync();
    return Results.Ok(shipments);
}).RequireAuthorization();

app.MapGet("/api/shipments/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
{
    var shipment = await db.Shipments.Where(s => s.TrackingNumber == trackingNumber)
        .Select(s => new ShipmentTracker.Client.Models.ShipmentDto
        {
            Id = s.Id,
            TrackingNumber = s.TrackingNumber,
            Origin = s.Origin,
            Destination = s.Destination,
            Status = s.Status,
            ShippedDate = s.ShippedDate,
            EstimatedDelivery = s.EstimatedDelivery
        }).FirstOrDefaultAsync();
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
}).RequireAuthorization();

app.MapPut("/api/shipments/{id}/status", async (int id, ShipmentTracker.Client.Models.ShipmentDto update, ApplicationDbContext db) =>
{
    var shipment = await db.Shipments.FindAsync(id);
    if (shipment is null) return Results.NotFound();
    shipment.Status = update.Status;
    await db.SaveChangesAsync();
    return Results.Ok();
}).RequireAuthorization();
```

Also add `using Microsoft.EntityFrameworkCore;` at the top of Program.cs (check if already there, it might be from the template).

## 5. Create the Dispatcher page (client-side)

Create file: `ShipmentTracker.Client/Pages/Dispatch.razor`
```razor
@page "/dispatch"
@using ShipmentTracker.Client.Models
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@inject HttpClient Http

<PageTitle>Dispatch Dashboard</PageTitle>

<h3>Dispatch Dashboard</h3>

@if (shipments == null)
{
    <p><em>Loading shipments...</em></p>
}
else
{
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Filter by destination..." @bind="filterText" @bind:event="oninput" />
    </div>

    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Shipped</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var s in FilteredShipments)
            {
                <tr>
                    <td>@s.TrackingNumber</td>
                    <td>@s.Origin</td>
                    <td>@s.Destination</td>
                    <td>
                        <span class="badge @GetStatusBadge(s.Status)">@s.Status</span>
                    </td>
                    <td>@s.ShippedDate.ToShortDateString()</td>
                    <td>@(s.EstimatedDelivery?.ToShortDateString() ?? "—")</td>
                    <td>
                        <select class="form-select form-select-sm" value="@s.Status" @onchange="(e) => UpdateStatus(s, e.Value?.ToString())">
                            <option value="Processing">Processing</option>
                            <option value="In Transit">In Transit</option>
                            <option value="Customs Hold">Customs Hold</option>
                            <option value="Out for Delivery">Out for Delivery</option>
                            <option value="Delivered">Delivered</option>
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<ShipmentDto>? shipments;
    private string filterText = string.Empty;

    private IEnumerable<ShipmentDto> FilteredShipments =>
        shipments!.Where(s => string.IsNullOrEmpty(filterText) 
            || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase));

    protected override async Task OnInitializedAsync()
    {
        shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("api/shipments");
    }

    private async Task UpdateStatus(ShipmentDto shipment, string? newStatus)
    {
        if (string.IsNullOrEmpty(newStatus) || newStatus == shipment.Status) return;
        shipment.Status = newStatus;
        await Http.PutAsJsonAsync($"api/shipments/{shipment.Id}/status", shipment);
    }

    private string GetStatusBadge(string status) => status switch
    {
        "Processing" => "bg-secondary",
        "In Transit" => "bg-primary",
        "Customs Hold" => "bg-warning text-dark",
        "Out for Delivery" => "bg-info",
        "Delivered" => "bg-success",
        _ => "bg-secondary"
    };
}
```

## 6. Create the Customer tracking page (client-side)

Create file: `ShipmentTracker.Client/Pages/Track.razor`
```razor
@page "/track"
@using ShipmentTracker.Client.Models
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]
@inject HttpClient Http

<PageTitle>Track Shipment</PageTitle>

<h3>Track Your Shipment</h3>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g. TRK-100201)" @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchShipment" disabled="@isLoading">
                @if (isLoading)
                {
                    <span class="spinner-border spinner-border-sm" role="status"></span>
                }
                else
                {
                    <span>Track</span>
                }
            </button>
        </div>
    </div>
</div>

@if (notFound)
{
    <div class="alert alert-warning">No shipment found with tracking number <strong>@searchedNumber</strong>.</div>
}

@if (shipment != null)
{
    <div class="card">
        <div class="card-header">
            <strong>@shipment.TrackingNumber</strong>
            <span class="badge @GetStatusBadge(shipment.Status) ms-2">@shipment.Status</span>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <p><strong>Origin:</strong> @shipment.Origin</p>
                    <p><strong>Destination:</strong> @shipment.Destination</p>
                </div>
                <div class="col-md-6">
                    <p><strong>Shipped:</strong> @shipment.ShippedDate.ToShortDateString()</p>
                    <p><strong>Estimated Delivery:</strong> @(shipment.EstimatedDelivery?.ToShortDateString() ?? "Pending")</p>
                </div>
            </div>
            @if (shipment.Status == "Delivered")
            {
                <div class="alert alert-success mt-3 mb-0">Your shipment has been delivered!</div>
            }
            else if (shipment.EstimatedDelivery.HasValue)
            {
                var daysLeft = (shipment.EstimatedDelivery.Value - DateTime.Today).Days;
                <div class="alert alert-info mt-3 mb-0">
                    @if (daysLeft > 0)
                    {
                        <span>Estimated to arrive in <strong>@daysLeft day(s)</strong>.</span>
                    }
                    else
                    {
                        <span>Delivery is expected today or is running late.</span>
                    }
                </div>
            }
        </div>
    </div>
}

@code {
    private string trackingNumber = string.Empty;
    private string searchedNumber = string.Empty;
    private ShipmentDto? shipment;
    private bool notFound;
    private bool isLoading;

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isLoading = true;
        notFound = false;
        shipment = null;
