+            ShippedDate = s.ShippedDate,
+            EstimatedDelivery = s.EstimatedDelivery
+        }).FirstOrDefaultAsync();
+    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
+}).RequireAuthorization();
+
+app.MapPut("/api/shipments/{id}/status", async (int id, ShipmentTracker.Client.Models.ShipmentDto update, ApplicationDbContext db) =>
+{
+    var shipment = await db.Shipments.FindAsync(id);
+    if (shipment is null) return Results.NotFound();
+    shipment.Status = update.Status;
+    await db.SaveChangesAsync();
+    return Results.Ok();
+}).RequireAuthorization();
+
 app.Run();

